let __v_299 = Value::from("Cancel and block first, in this order: freeze every card in your bank's app, ask your network to bar the phone, then report it to the police on 101 for a crime reference number, which your insurance will ask for. If your keys and address were both in the bag, get the locks changed rather than hoping, and tell the bank you are worried about your address too. Most home insurance covers a bag taken away from home, and most policies want to hear within a few days.");
frame.store("STOLEN_BAG", __v_299.clone())?;
