let __v_301 = Value::from("Report it to the police where you are and get a written report - a copy in English if you can - because your travel insurer and any replacement passport both ask for one. Then freeze the cards in your bank's app, have your network bar the phone, and ring your embassy or consulate if the passport went with it. Take photos of the report on your phone; paper gets lost.");
frame.store("STOLEN_BAG_AWAY", __v_301.clone())?;
